#!/usr/bin/env bash
# no-attribution.sh - Claude Code PreToolUse hook for the Bash tool: block a
# git commit, or a gh pr create/edit, whose message carries a co-author or
# attribution tag, whoever it names: a Co-Authored-By, Co-developed-by,
# Assisted-by, Generated-by or session-link trailer, or a line that starts
# "Generated with" or "Generated by" (a credit line).  The message is looked
# for in the command itself (-m, --body, a heredoc) and in any file it passes
# with -F, --file or --body-file (a relative path is taken from the event's
# cwd).  Words that merely appear in a sentence are not tags.
# Exit 2 blocks the call, and Claude Code shows Claude the message on stderr;
# anything else lets it run.  Installed by setup/claude/setup.sh, which adds
# it to hooks.PreToolUse in settings.json next to any hooks already there.

INPUT=$(cat)
# without jq, search the raw event: the command is in it, JSON-escaped
if command -v jq > /dev/null; then
  CMD=$(jq -r '.tool_input.command // empty' <<< "$INPUT" 2> /dev/null)
  CWD=$(jq -r '.cwd // empty' <<< "$INPUT" 2> /dev/null)
else
  CMD=$INPUT
  CWD=""
fi
[[ -z $CMD ]] && exit 0

# a commit (git, then any global options, then commit) or a PR create/edit
GIT_COMMIT='(^|[^[:alnum:]_./-])git([[:space:]]+(-[Cc][[:space:]]+[^[:space:]]+|--?[[:alnum:]][-[:alnum:]]*(=[^[:space:]]+)?))*[[:space:]]+commit([^-[:alnum:]]|$)'
GH_PR='(^|[^[:alnum:]_./-])gh[[:space:]]+pr[[:space:]]+(create|edit)([^-[:alnum:]]|$)'
grep -qE -- "$GIT_COMMIT|$GH_PR" <<< "$CMD" || exit 0

# a trailer anywhere (also inside a one-line $'...' message), or a credit
# line at the start of a line or after a literal \n
TAG='(co-authored-by|co-developed-by|assisted-by|generated-by|claude-session)[[:space:]]*:'
CREDIT='(^|\\n)[[:space:]]*(🤖[[:space:]]*)?generated (with|by) |🤖[[:space:]]*generated (with|by) '
ATTRIBUTION="$TAG|$CREDIT"
TEXT=$CMD
while IFS= read -r FILE; do
  FILE=${FILE#[\"\']}
  FILE=${FILE%[\"\']}
  [[ -z $FILE || $FILE == - ]] && continue
  [[ $FILE != /* && -n $CWD ]] && FILE="$CWD/$FILE"
  [[ -f $FILE && -r $FILE ]] && TEXT+=$'\n'$(cat -- "$FILE")
done < <(grep -oE -- '(^|[[:space:]])(-F|--file|--body-file)(=|[[:space:]]+)[^[:space:]]+' <<< "$CMD" |
  sed -E 's/^[[:space:]]*(-F|--file|--body-file)(=|[[:space:]]+)//')

FOUND=$(grep -iE -- "$ATTRIBUTION" <<< "$TEXT" | sort -u)
[[ -z $FOUND ]] && exit 0
{
  echo "Blocked by no-attribution.sh: this commit or pull request carries a co-author or attribution tag, which is not allowed."
  echo "Remove these lines and run it again:"
  while IFS= read -r LINE; do echo "  $LINE"; done <<< "$FOUND"
} >&2
exit 2
